    ANTERIOR_JANEIRO.TOTAL_VALOR TOTAL_JANEIRO,
    ANTERIOR_FEVEREIRO.QUANTIDADE QUANTIDADE_FEVEREIRO,
    ANTERIOR_FEVEREIRO.TOTAL_VALOR TOTAL_FEVEREIRO,
    ANTERIOR_MARCO.QUANTIDADE QUANTIDADE_MARCO,
    ANTERIOR_MARCO.TOTAL_VALOR TOTAL_MARCO,
    ATUAL_ABRIL.QUANTIDADE QUANTIDADE_ABRIL,
    ATUAL_ABRIL.TOTAL_VALOR TOTAL_ABRIL
FROM
    (
    SELECT
        'UMS_ITAIN' ORGAO,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        COUNT(R.COD_RUBRICA) QUANTIDADE,
        SUM(FR.VALOR_CALCULADO) TOTAL_VALOR
    FROM
        SW_UMS_ITAIN.FOLHA FO
        JOIN SW_UMS_ITAIN.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_UMS_ITAIN.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    WHERE
        FO.MES = 1
        AND FO.ANO = 2026
        AND R.COD_RUBRICA IN (112992, 112987, 112855)
    GROUP BY
        'UMS_ITAIN',
        R.COD_RUBRICA,
        R.NOME_RUBRICA
    ) ANTERIOR_JANEIRO
    LEFT JOIN (
    SELECT
        'UMS_ITAIN' ORGAO,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        COUNT(R.COD_RUBRICA) QUANTIDADE,
        SUM(FR.VALOR_CALCULADO) TOTAL_VALOR
    FROM
        SW_UMS_ITAIN.FOLHA FO
        JOIN SW_UMS_ITAIN.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_UMS_ITAIN.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    WHERE
        FO.MES = 2
        AND FO.ANO = 2026
        AND R.COD_RUBRICA IN (112992, 112987, 112855)
    GROUP BY
        'UMS_ITAIN',
        R.COD_RUBRICA,
        R.NOME_RUBRICA
    ) ANTERIOR_FEVEREIRO ON ANTERIOR_FEVEREIRO.COD_RUBRICA = ANTERIOR_JANEIRO.COD_RUBRICA
    LEFT JOIN (
    SELECT
        'UMS_ITAIN' ORGAO,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        COUNT(R.COD_RUBRICA) QUANTIDADE,
        SUM(FR.VALOR_CALCULADO) TOTAL_VALOR
    FROM
        SW_UMS_ITAIN.FOLHA FO
        JOIN SW_UMS_ITAIN.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_UMS_ITAIN.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    WHERE
        FO.MES = 3
        AND FO.ANO = 2026
        AND R.COD_RUBRICA IN (112992, 112987, 112855)
    GROUP BY
        'UMS_ITAIN',
        R.COD_RUBRICA,
        R.NOME_RUBRICA
    ) ANTERIOR_MARCO ON ANTERIOR_MARCO.COD_RUBRICA = ANTERIOR_JANEIRO.COD_RUBRICA
    LEFT JOIN (
    SELECT
        'UMS_ITAIN' ORGAO,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        COUNT(R.COD_RUBRICA) QUANTIDADE,
        SUM(FR.VALOR_CALCULADO) TOTAL_VALOR
    FROM
        SW_UMS_ITAIN.FOLHA FO
        JOIN SW_UMS_ITAIN.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_UMS_ITAIN.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    WHERE
        FO.MES = 4
        AND FO.ANO = 2026
        AND R.COD_RUBRICA IN (112992, 112987, 112855)
    GROUP BY
        'UMS_ITAIN',
        R.COD_RUBRICA,
        R.NOME_RUBRICA
    ) ATUAL_ABRIL ON ATUAL_ABRIL.COD_RUBRICA = ANTERIOR_JANEIRO.COD_RUBRICA

UNION ALL

SELECT
    ANTERIOR_JANEIRO.ORGAO,
