        R.COD_RUBRICA,
        R.NOME_RUBRICA
    ) ANTERIOR_MARCO ON ANTERIOR_MARCO.COD_RUBRICA = ANTERIOR_JANEIRO.COD_RUBRICA
    LEFT JOIN (
    SELECT
