        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        COUNT(R.COD_RUBRICA) QUANTIDADE,
        SUM(FR.VALOR_CALCULADO) TOTAL_VALOR
    FROM
        SW_UMS_PAES.FOLHA FO
        JOIN SW_UMS_PAES.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_UMS_PAES.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    WHERE
